    const mn=Math.min(...pts)-2,mx=Math.max(...pts)+2;const W=300,H=120;const X=i=>20+i*(W-40)/Math.max(1,pts.length-1),Y=v=>H-14-(v-mn)/Math.max(1,mx-mn)*(H-30);
