function renderDev(embed){const ut=SL.userTeam();if(embed)return renderDev0(true);let h=hubTabs('dev');if(!DEV_SUBS.includes(ui.sub.dev))ui.sub.dev='train';if(ui.sub.dev==='equip')return h+`<div class="stv">${renderEquip(ut)}</div>`;if(ui.sub.dev==='train'){const v=ui.trV||'set';h+=`<div class="htabs2 hs">${[['set','훈련 설정'],['info','성장정보']].map(x=>`<button class="sg${v===x[0]?' on':''}" onclick="UI.set('trV','${x[0]}')">${x[1]}</button>`).join('')}</div>`;if(v==='info')return h+`<div class="stv">${renderGrowInfo(ut)}</div>`;}if(ui.sub.dev==='train')return h+renderTrainMock(ut);if(ui.sub.dev==='res'){const r=renderReserve(ut);const i=r.indexOf('<div class="grptab">');const j=i>=0?r.indexOf('<div class="mkbtn3">',i):-1;const k=j>=0?r.indexOf('</div>',j)+6:-1;const rest=i>=0&&k>0?r.slice(0,i)+r.slice(k):r;return h+rest+renderProspectMock(ut)+mkBtn2(`<button class="ghost big" onclick="UI.go('league','fut')">🏟 2군 리그 순위·결과</button>`,`<button class="ghost big" onclick="UI.go('roster','list');UI.sqf('grp','R')">👥 2군 명단</button>`);}const inner=renderDev0(false);return inner;}
