  const inc=[['🎟 입장 수입','tickets'],['📺 메인 스폰서','sponsor'],['🤝 광고 · 광고 수수료',null,(x)=>(x.ads||0)+(x.endorse||0)],['🏆 리그 배당 · 지원금',null,x=>(x.dividend||0)+(x.grant||0)],['💱 선수 판매','sales']];const out=[['👥 선수단 연봉 지출','salary'],['🏢 구단 운영비 (시설·육성 등)',null,x=>(x.facility||0)+(x.scout||0)+(x.staff||0)+(x.dispatch||0)+(x.other||0)],['💼 영입·계약금','buys']];
