  h+=`<div class="mkcard" style="padding:0">${mkSec(`${yr} 시즌 ${lab[f.sp]} 기록`)}<table class="mkt mini"><thead><tr><th class="tn">${f.sp==='month'?'월':f.sp==='opp'?'상대':'구분'}</th>${H}</tr></thead><tbody>${keys.map(k=>`<tr><td class="tn"><span class="tcl">${esc(k)}</span></td>${statRow(p,sp[k]).map(x=>`<td class="tc">${x}</td>`).join('')}</tr>`).join('')||'<tr><td colspan="8" class="muted">이번 시즌 경기 기록이 아직 없습니다.</td></tr>'}</tbody></table></div>`;
