// ---- 어느 표든 제목을 누르면 정렬 (FM·프로야구 게임식). 직접 정렬을 가진 제목(.srt)은 제외 ----
const POS_TXT={SP:1,RP:2,CP:3,CL:3,P:2,C:4,'1B':5,'2B':6,'3B':7,SS:8,LF:9,CF:10,RF:11,OF:10,IF:6,DH:12,'선발':1,'불펜':2,'마무리':3,'포수':4,'1루수':5,'2루수':6,'3루수':7,'유격수':8,'좌익수':9,'중견수':10,'우익수':11,'지명타자':12};
const GRADE_TXT={S:6,A:5,B:4,C:3,D:2,E:1};
function cellKey(td){const t=(td.innerText||td.textContent||'').replace(/\s+/g,' ').trim();if(!t||t==='-'||t==='–')return {n:null,s:''};
  const w=t.split(' ')[0];if(POS_TXT[w]!=null&&t.length<=8)return {n:POS_TXT[w],s:t,pos:1};
  let m=t.match(/^([SABCDE])\s?(\d+)/);if(m)return {n:GRADE_TXT[m[1]]*1000+(+m[2]),s:t};
  m=t.match(/(-?[\d,]*\.?\d+)\s*억(?:\s*(\d[\d,]*)\s*만)?/);if(m)return {n:parseFloat(m[1].replace(/,/g,''))*10000+(m[2]?+m[2].replace(/,/g,''):0),s:t};
  m=t.match(/(-?[\d,]+)\s*만/);if(m)return {n:+m[1].replace(/,/g,''),s:t};
  m=t.match(/^([▲▼→]?)\s*([+\-−]?)\s*(\d[\d,]*\.?\d*)/);if(m){let v=parseFloat(m[3].replace(/,/g,''));if(m[2]==='-'||m[2]==='−'||(m[1]==='▼'&&!m[2]))v=-v;return {n:v,s:t};}
  m=t.match(/^(\d+)(?:\.(\d+))?[위세년차번%]/);if(m)return {n:parseFloat(m[0]),s:t};
  return {n:null,s:t};}
function tblHead(tb){if(tb.tHead&&tb.tHead.rows.length)return tb.tHead.rows[tb.tHead.rows.length-1];const b=tb.tBodies[0];if(!b||!b.rows.length)return null;const r=b.rows[0];return r.cells.length&&[...r.cells].every(c=>c.tagName==='TH')?r:null;}
function tblSig(tb){const hr=tblHead(tb);return (ui.view?ui.view.type+':':ui.tab+':'+(ui.sub[ui.tab]||'')+':')+[...hr.cells].map(th=>(th.dataset.lab||th.textContent).trim()).join('|');}
function tblRows(tb){const b=tb.tBodies[0];const hr=tblHead(tb);if(!b||!hr)return null;const n=hr.cells.length;const rows=[...b.rows].filter(r=>r!==hr&&r.cells.length===n&&!r.classList.contains('nosort'));if(rows.length<2)return null;const other=[...b.rows].filter(r=>r!==hr&&r.cells.length!==n);if(other.length>2)return null;return rows;}
function sortTable(tb,ci,dir){const rows=tblRows(tb);if(!rows)return;const hr=tblHead(tb);const ks=rows.map((r,i)=>({r,i,k:cellKey(r.cells[ci])}));const num=ks.filter(x=>x.k.n!=null).length>=ks.filter(x=>x.k.s).length*0.6;
  ks.sort((a,b)=>{let c;if(num){if(a.k.n==null&&b.k.n==null)c=0;else if(a.k.n==null)return 1;else if(b.k.n==null)return -1;else c=a.k.n-b.k.n;}else{if(!a.k.s&&b.k.s)return 1;if(!b.k.s&&a.k.s)return -1;c=a.k.s.localeCompare(b.k.s,'ko');}return (c*dir)||(a.i-b.i);});
  const body=tb.tBodies[0];for(const r of body.rows)if(r!==hr&&r.cells.length!==hr.cells.length)r.style.display='none';for(const x of ks)body.appendChild(x.r);
  [...hr.cells].forEach((th,i)=>{th.classList.toggle('son',i===ci);const ic=th.querySelector('i.as');if(ic)ic.textContent=i===ci?(dir>0?'▲':'▼'):'⇅';});}
function decorateTables(){ui.tsort=ui.tsort||{};const app=document.getElementById('app')||document.body;
  for(const tb of app.querySelectorAll('table')){if(tb.classList.contains('nosort')||tb.matches('.negt,.kvt,.rnw')||(tblRows(tb)||[]).length<4)continue;const hr=tblHead(tb);if(!hr||!tblRows(tb))continue;const ths=[...hr.cells];if(ths.some(th=>th.colSpan>1))continue;
    tb.classList.add('asort');ths.forEach((th,i)=>{if(th.classList.contains('srt')||th.getAttribute('onclick'))return;if(!th.dataset.lab)th.dataset.lab=th.textContent.trim();if(!th.querySelector('i.as'))th.insertAdjacentHTML('beforeend',' <i class="as">⇅</i>');th.classList.add('asc0');th.onclick=()=>{const sig=tblSig(tb);const cur=ui.tsort[sig];const first=(()=>{const rows=tblRows(tb);if(!rows)return 1;const k=cellKey(rows[0].cells[i]);return k.n!=null&&!k.pos?-1:1;})();const dir=cur&&cur.c===i?-cur.d:first;ui.tsort[sig]={c:i,d:dir};sortTable(tb,i,dir);};});
    const st=ui.tsort[tblSig(tb)];if(st&&ths[st.c])sortTable(tb,st.c,st.d);}}
