function searchHtml(q){const ut=SL.userTeam();q=(q||'').trim();if(!q)return '<div class="muted small" style="padding:8px">이름 두 글자 이상 (예: 김민, 페레스)</div>';
  const all=Object.values(S.players).filter(p=>p&&!p.retired&&p.name&&p.name.includes(q));const rk=p=>(p.teamId===ut.id||ut.dev.includes(p.id)?0:p.teamId==null?1:S.teams[p.teamId]&&S.teams[p.teamId].league===ut.league?2:3);all.sort((a,b)=>rk(a)-rk(b)||SL.calcOvr(b)-SL.calcOvr(a));
  const lab=p=>{const r=rk(p);return r===0?'<span class="chip g">우리</span>':r===1?'<span class="chip y">FA</span>':`<span class="muted">${esc(S.teams[p.teamId]?S.teams[p.teamId].name:'')}</span>`;};
  return all.slice(0,30).map(p=>`<div class="prow act" onclick="UI.closeModal();UI.openPlayer(${p.id})">${face(p,34)}<div class="grow"><div class="nm">${esc(p.name)} <span class="muted small">${p.pos} · ${p.age}세</span></div><div class="sub small">${lab(p)}</div></div><b>${hidOf(p)?'?':Math.round(SL.calcOvr(p))}</b></div>`).join('')||'<div class="muted small" style="padding:8px">찾는 선수가 없습니다.</div>';}
