  if(!S.liveGame&&!ui.view&&(e.key==='q'||e.key==='e'||e.key==='Q'||e.key==='E')){const seq=screenSeq();const [t,sb]=curScreen();let i=seq.findIndex(x=>x[0]===t&&x[1]===sb);if(i<0)i=seq.findIndex(x=>x[0]===t);const j=(i+(/e/i.test(e.key)?1:-1)+seq.length)%seq.length;e.preventDefault();const x=seq[j];if(x[1])A.go(x[0],x[1]);else A.setTab(x[0]);return;}
