function winterDue(pv,it){const W=SL.BAL.OFFSEASON_WEEKS;if(pv.loss.length)return `<span class="bad">다음 진행 시 ${esc(pv.loss[0].text)}</span>`;{const d=(it||[]).filter(x=>!/개막 전까지/.test(x.tag)&&x.grp!=='later').map(x=>{const m=x.tag.match(/(\d+)주차까지|(\d+)(?:주|일) 남음|이번 주/);return m?{x,w:m[1]?+m[1]:m[2]?S.week+(+m[2]):S.week}:null;}).filter(Boolean).sort((a,b)=>a.w-b.w)[0];if(d){const same=(it||[]).filter(x=>{const m=x.tag.match(/(\d+)주차까지|(\d+)(?:주|일) 남음|이번 주/);if(!m)return false;const w=m[1]?+m[1]:m[2]?S.week+(+m[2]):S.week;return w===d.w;}).map(x=>x.tag.split(' · ')[0]);return `마감 ${d.w<=S.week?'이번 주 끝':d.w+'주차 끝'} · ${esc([...new Set(same)].slice(0,2).join(', '))}`;}}if(S.week<=2&&S.pendingFA.length)return `다음 마감 · 재계약 2주차 끝`;if(S.draft&&!S.draft.done)return '신인 지명 진행 중';if(SL.draftPending().length)return '다음 마감 · 신인 계약 개막 전';return S.week<=W?`개막까지 ${W-S.week+1}주`:'개막 준비 완료';}
