Object.assign(A,{
  eqF(k,v){ui.eqF=ui.eqF||{v:'on',side:'B'};ui.eqF[k]=v;ui.keepScroll=true;render();},
  eqSide(s){ui.eqF=ui.eqF||{v:'on',side:'B'};ui.eqF.side=s;ui.eqF.pid=null;ui.eqF.item=null;render();},
  eqBuyAsk(k){const x=SL.EQUIP[k];if(!x)return;modal(`<div class="stvmenu"><div class="mt">${esc(x.name)} <small>${esc(eqFxTxt(x))}</small></div><div class="small" style="padding:4px 2px 8px">${Ms(x.cost)} — 이대로 사시겠습니까?</div><button class="primary" onclick="UI.eqBuyGo('${k}')">사기</button><button class="ghost" onclick="UI.closeModal()">아니오</button></div>`);},
  eqBuyGo(k){if(!once('eqb'))return;const e=SL.eqBuy(k);closeModal();if(e){toast(e,3000);return;}sfx('cash');autosave();modal(`<div class="stvmenu"><div class="mt">구매 완료</div><div class="small" style="padding:4px 2px 8px">${esc(SL.josa(SL.EQUIP[k].name,'이','가'))} 보관함에 들어갔습니다. 「장비관리」에서 선수에게 끼우세요.</div><button class="primary" onclick="UI.closeModal();UI.eqF('v','on')">장비관리로</button><button class="ghost" onclick="UI.closeModal();UI.render()">더 사기</button></div>`);},
  eqOnGo(pid,k){const e=SL.eqOn(pid,k);if(e)toast(e,2600);else{toast(`${S.players[pid].name}: ${SL.EQUIP[k].name} 장착`,2000);autosave();}ui.keepScroll=true;render();},
  eqOffAsk(pid,i){const p=S.players[pid];const k=p&&p.eq&&p.eq[i];if(!k)return;stvMenu(`${esc(p.name)} · ${esc(SL.EQUIP[k].name)}`,[['빼서 보관함으로',`UI.eqOffGo(${pid},${i})`,'primary']]);},
  eqOffGo(pid,i){const e=SL.eqOff(pid,i);if(e)toast(e);autosave();ui.keepScroll=true;render();}});

// ======================= v84 (R068): 코치관리 — EA 2011 코치관리 칸 + 상점 「코치 카드」 고르기를 한 흐름으로 =======================
const CO_C={bat:'#e74c3c',pit:'#f1c40f',def:'#3498db',dev:'#2ecc71',scout:'#9b59b6',med:'#1abc9c'};
function renderStaff(ut){const ST=SL.BAL.STAFF;const sm=SL.staffSummary(ut);const staff=ut.staff||[];const exp=staff.filter(c=>c.years<=0).length;
  let h=`<div class="stv">`+stvHead('코치관리',`<span class="stvc">코치 <b>${staff.filter(c=>c.years>0).length}</b>명 · 인건비 <b>${Ms(SL.staffPay(ut))}</b>/시즌${exp?` · <b class="bad">만료 ${exp}</b>`:''}</span>`)+stvMoney();
  for(const d in ST){const x=sm[d];const mine=staff.filter(c=>c.dept===d).sort((a,b)=>b.rating-a.rating);
    h+=`<div class="cod"><div class="coh"><i style="background:${CO_C[d]||'#888'}"></i><b>${esc(x.name)}</b><small>${x.n}/${x.max}</small><span class="${x.tone==='up'?'ok':x.tone==='dn'?'bad':''}">${esc(x.eff)}</span></div><div class="cos">${mine.map(c=>{const g=SL.gradeOf(c.rating);return `<button class="co ${c.years<=0?'exp':''}" onclick="UI.coachMenu(${c.id})">${coachFace(c,34)}<span><b>${esc(c.name)}</b><small><em class="g ${g}">${g}</em>${c.rating} · ${c.years>0?`${c.years}년 남음`:'<b class="bad">계약 만료</b>'}</small></span></button>`;}).join('')}${x.n<x.max?`<button class="co emp" onclick="UI.coachScout('${d}')"><span class="e">EMPTY</span><span><b>빈자리 ${x.max-x.n}</b><small>${esc(x.what)} — 영입 ›</small></span></button>`:''}</div></div>`;}
  h+=`<div class="stvsub small muted">칸을 누르면 재계약·해임, EMPTY를 누르면 그 부서 후보를 ◀ ▶로 넘겨 보며 바로 영입. 같은 부서 둘째부터는 효과가 줄어듭니다(리그 평균 코치진 대비).</div></div>`;
  return h+driveCard(ut);}
function coachScoutHtml(d){const ST=SL.BAL.STAFF;const L=(S.staffPool||[]).filter(c=>c.dept===d).sort((a,b)=>b.rating-a.rating);ui.csI=ui.csI||{};let i=Math.min(ui.csI[d]||0,Math.max(0,L.length-1));const c=L[i];const ut=SL.userTeam();const yrs=ui.coachYears||2;
  if(!c)return `<div class="stvmenu"><div class="mt">${esc(ST[d].name)} 후보 없음</div><div class="small" style="padding:6px 2px">스토브리그마다 새 후보가 나옵니다.</div><button class="ghost" onclick="UI.closeModal()">닫기</button></div>`;
  const tm=SL.coachTerms(c);const g=SL.gradeOf(c.rating);
  return `<div class="stvmenu cosc"><div class="mt">${esc(ST[d].name)} 영입 <small>${i+1}/${L.length}</small></div>
    <div class="card3"><button aria-label="이전 후보" onclick="UI.coachScoutI('${d}',${i-1})" ${i>0?'':'disabled'}>◀</button><div class="cc">${coachFace(c,64)}<b>${esc(c.name)}</b><small>${c.age}세${c.nat!=='KR'?' · '+esc(SL.NAT_KO[c.nat]):''} · <em class="g ${g}">${g}</em> ${c.rating}</small><small>${esc(c.bio)}${c.trait?` · ${esc(c.trait)}`:''}</small></div><button aria-label="다음 후보" onclick="UI.coachScoutI('${d}',${i+1})" ${i<L.length-1?'':'disabled'}>▶</button></div>
    <div class="small" style="text-align:center;margin:4px 0">${esc(ST[d].what)}</div>
    <div class="seg" style="margin:6px 0">${[1,2,3].map(y=>`<button class="${yrs===y?'on':''}" onclick="UI.coachYearsM('${d}',${y})">${y}년</button>`).join('')}</div>
    <div class="eqcost"><span>연봉</span><b>${Ms(tm.salary)}/시즌</b><span>구단 자금</span><b>${Ms(ut.cash)}</b></div>${tm.why?`<div class="small ${tm.ok?'':'bad'}" style="margin:4px 2px">${esc(tm.why)}</div>`:''}
    <button class="primary" ${tm.ok?'':'disabled'} onclick="UI.coachHireAsk(${c.id},'${d}')">${tm.ok?`${yrs}년 계약으로 영입`:'영입 불가'}</button><button class="ghost" onclick="UI.closeModal()">닫기</button></div>`;}
Object.assign(A,{
  coachScout(d){modal(coachScoutHtml(d));},
  coachScoutI(d,i){ui.csI=ui.csI||{};ui.csI[d]=Math.max(0,i);modal(coachScoutHtml(d));},
  coachYearsM(d,y){ui.coachYears=y;modal(coachScoutHtml(d));},
  coachHireAsk(id,d){const c=(S.staffPool||[]).find(x=>x.id===id);if(!c)return;const tm=SL.coachTerms(c);modal(`<div class="stvmenu"><div class="mt">${esc(c.name)} 코치 영입</div><div class="small" style="padding:4px 2px 8px">${ui.coachYears||2}년 · 연봉 ${Ms(tm.salary)}/시즌 — 이대로 영입하시겠습니까?</div><button class="primary" onclick="UI.closeModal();UI.hireCoach(${id})">영입</button><button class="ghost" onclick="UI.coachScout('${d}')">아니오</button></div>`);},
  coachMenu(id){const ut=SL.userTeam();const c=(ut.staff||[]).find(x=>x.id===id);if(!c)return;const off=S.phase==='offseason';const sev=SL.severanceOf(c);
    stvMenu(`${esc(c.name)} <small>${esc(SL.BAL.STAFF[c.dept].name)} · ${SL.gradeOf(c.rating)} ${c.rating} · ${c.years>0?c.years+'년 남음 · 연봉 '+Ms(c.salary):'계약 만료 · 요구 '+Ms(SL.renewDemand(c))}</small>`,[c.years<=0?[off?`재계약 ${ui.coachYears||2}년`:'재계약은 스토브리그에',`UI.renewCoach(${id})`,'primary',!off]:null,[`해임${sev?' (보상 '+Ms(sev)+')':''}`,`UI.fireCoach(${id})`,'danger'],[`${esc(SL.BAL.STAFF[c.dept].name)} 후보 보기`,`UI.coachScout('${c.dept}')`]]);}});

// ======================= v85 (R069): EA 2011 성장관리 · 팀정보 · 예산관리 =======================
// 성장정보 — 왼쪽 선수 목록(시즌 변화) + 오른쪽 상세(연차·연봉 · 능력 막대 + 기준 대비 변화)
function renderGrowInfo(ut){const f=ui.giF=ui.giF||{side:'B'};const side=f.side;const ps=ut.roster.concat(ut.dev).map(id=>S.players[id]).filter(p=>p&&(side==='P'?SL.isPitcher(p):!SL.isPitcher(p))).sort((a,b)=>SL.calcOvr(b)-SL.calcOvr(a));const sel=ps.find(p=>p.id===f.pid)||ps[0];
  let h=stvHead('성장정보',`<span class="stvc">${side==='P'?'투수':'타자'} ${ps.length}명</span>`)+stvTabs(side,"UI.giSide");
  const dl=p=>{const d=SL.seasonDelta(p);return d&&d.d?`<em class="${d.d>0?'ok':'bad'}">${d.d>0?'▲':'▼'}${Math.abs(d.d)}</em>`:'<em class="muted">-</em>';};
  h+=`<div class="eqman gi"><div class="eql">${ps.map(p=>`<button class="${sel&&p.id===sel.id?'on':''}" onclick="UI.giSel(${p.id})"><span>${esc(p.name)}</span><small>${posChip(p)} ${Math.round(SL.calcOvr(p))} ${dl(p)}</small></button>`).join('')}</div>`;
  if(sel){const B=SL.growthBase(sel);const keys=SL.isPitcher(sel)?SL.PIT_KEYS:SL.BAT_KEYS;const yrs=(sel.hist||[]).length+1;
    h+=`<div class="eqr"><div class="gih">${face(sel,44)}<div><b>${esc(sel.name)}</b><small>${sel.pos} · ${sel.age}세 · ${yrs}년차</small><small>연봉 ${Ms(sel.contract?sel.contract.salary:0)}${sel.contract?` · ${sel.contract.years}년 남음`:''}</small></div></div>
      <div class="gib"><div class="gibh"><span>종합</span><b>${Math.round(SL.calcOvr(sel))}</b>${dl(sel)}</div>${keys.map(k=>{const v=Math.round(sel.attrs[k]||0);const b0=B&&B.attrs?Math.round(B.attrs[k]||0):v;const d=v-b0;return `<div class="gir"><span>${esc(SL.ATTR_KO[k])}</span><i><s style="width:${v}%"></s></i><b>${v}</b><em class="${d>0?'ok':d<0?'bad':'muted'}">${d?((d>0?'+':'')+d):''}</em></div>`;}).join('')}</div>
      <div class="small muted" style="margin-top:4px">변화 = ${esc(B?B.label||'시즌 시작 대비':'기준 없음')} · 훈련 방향 ${esc((SL.isPitcher(sel)?SL.FOCUS_PIT:SL.FOCUS_BAT)[sel.focus||'balance']||'균형')}</div>
      <div class="stvact"><button onclick="UI.openPlayer(${sel.id})">선수 상세</button></div></div>`;}
  return h+`</div>`;}
// 팀정보 — 우리 팀 지표와 리그 순위 (지금 선수단 기준 + 득실은 구단 기록)
function teamInfoHtml(){const ut=SL.userTeam();const cp=SL.compOf(ut);const ts=SL.compTeams(cp);
  const agg=t=>{const o={ab:0,h:0,hr:0,sb:0,bb:0,outs:0,er:0,so:0};for(const id of t.roster){const p=S.players[id];const c=p&&p.cur;if(!c)continue;o.ab+=c.ab||0;o.h+=c.h||0;o.hr+=c.hr||0;o.sb+=c.sb||0;o.bb+=c.bb||0;o.outs+=c.pOuts||0;o.er+=c.pER||0;o.so+=c.pSO||0;}
    const g=Math.max(1,t.rec.w+t.rec.l+(t.rec.tie||0));return {avg:o.ab?o.h/o.ab:0,era:o.outs?o.er*27/o.outs:0,hr:o.hr,sb:o.sb,so:o.so,rs:(t.rec.rs||0)/g,ra:(t.rec.ra||0)/g};};
  const A={};for(const t of ts)A[t.id]=agg(t);const rk=(k,asc)=>{const v=ts.map(t=>A[t.id][k]).sort((a,b)=>asc?a-b:b-a);return v.indexOf(A[ut.id][k])+1;};const n=ts.length;const me=A[ut.id];const played=ut.rec.w+ut.rec.l>0;
  const rows=[['팀 타율',me.avg.toFixed(3).replace(/^0/,''),rk('avg')],['팀 방어율',me.era.toFixed(2),rk('era',true)],['팀 홈런',me.hr+'개',rk('hr')],['팀 도루',me.sb+'개',rk('sb')],['투수 탈삼진',me.so+'개',rk('so')],['경기당 득점',me.rs.toFixed(1),rk('rs')],['경기당 실점',me.ra.toFixed(1),rk('ra',true)]];
  const st=SL.standings(cp);const r=st.findIndex(t=>t.id===ut.id)+1;
  return `<div class="stv">${stvHead('팀정보',`<span class="stvc">${esc(SL.compName(cp))}</span>`)}<div class="tih">${emblem(ut,52)}<div><b>${esc(ut.name)}</b><small>${ut.rec.w}승 ${ut.rec.tie||0}무 ${ut.rec.l}패 · ${played?r+'위':'개막 전'}</small><small>구단 자금 ${Ms(ut.cash)}</small></div></div>
    <table class="stvt nosort tit"><tbody>${rows.map(x=>`<tr><td class="tn">☑ ${x[0]}</td><td><b>${played?x[1]:'-'}</b></td><td class="tr">${played?`리그 <b class="${x[2]<=3?'ok':x[2]>n-3?'bad':''}">${x[2]}위</b>`:'-'}</td></tr>`).join('')}</tbody></table>
    <div class="stvsub small muted">${n}개 구단 중 순위 · 타율·방어율·홈런·도루·탈삼진은 지금 선수단의 이번 시즌 기록 합, 득점·실점은 구단 경기 기록</div></div>`;}
function renderLeague(){if(ui.sub.league==='team'){return hubTabs('league')+teamInfoHtml();}return renderLeague0();}
Object.assign(A,{giSide(s){ui.giF=ui.giF||{};ui.giF.side=s;ui.giF.pid=null;render();},giSel(pid){ui.giF=ui.giF||{side:'B'};ui.giF.pid=pid;ui.keepScroll=true;render();},
  bShiftN(dir,n){let ok=0,e=null;for(let i=0;i<n;i++){e=SL.budgetShift(dir);if(e)break;ok++;}autosave();toast(ok?`예산 전환 ${ok}번 완료${e?' · '+e:''}`:(e||'전환할 수 없습니다'),3200);ui.bsN=1;render();},
  bsSet(k,v){ui[k]=v;ui.keepScroll=true;render();}});
// 예산관리 — 「전환금액 ▲▼ · 바뀐 뒤 잔액」 한 칸 (원작의 볼 → 예산 전환 칸 구성)
function budgetBoxHtml(ut){if(ut.league!=='KR')return '';const I=SL.budgetInfo();const dir=ui.bsDir||1;const n=Math.max(1,Math.min(3,ui.bsN||1));const B=SL.budget?SL.budget():null;const sh=B?(B.shift||0):0;const left=Math.max(0,dir>0?3-sh:3+sh);
  const xA=I.xferLeft-(dir>0?30000*n:-30000*n),wA=I.wageLeft+(dir>0?10000*n:-10000*n);
  return `<div class="stv bbox">${stvHead('예산관리',`<span class="stvc">이 방향 남은 전환 <b>${left}</b>번</span>`)}<div class="stvsort">${[[1,'이적 → 연봉'],[-1,'연봉 → 이적']].map(x=>`<button class="${dir===x[0]?'on':''}" onclick="UI.bsSet('bsDir',${x[0]})">${x[1]}</button>`).join('')}</div>
    <div class="bstep"><span>전환 횟수</span><button onclick="UI.bsSet('bsN',${Math.max(1,n-1)})">▼</button><b>${n}</b><button onclick="UI.bsSet('bsN',${Math.min(3,n+1)})">▲</button><small>${dir>0?`이적 ${3*n}억 → 연봉 ${n}억`:`연봉 ${n}억 → 이적 ${3*n}억`}</small></div>
    <div class="eqcost"><span>이적 잔액</span><b>${Ms(Math.max(0,I.xferLeft))} → <span class="${xA<0?'bad':''}">${Ms(xA)}</span></b><span>연봉 여유</span><b>${Ms(I.wageLeft)} → <span class="${wA<0?'bad':''}">${Ms(wA)}</span></b></div>
    <div class="stvact"><button class="go" ${left?'':'disabled'} onclick="UI.bShiftN(${dir},${Math.min(n,left)})">전환</button></div></div>`;}
